"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7219],{82635:e=>{e.exports=JSON.parse('{"functions":[{"name":"WaitForPrimaryPart","desc":"Returns the model\'s `PrimaryPart`, waiting for it to appear if it is not set yet.\\n\\nReturns immediately when the `PrimaryPart` already exists, and returns `nil` if\\nthe timeout passes without one being assigned \u2014 always check the result.\\n\\n```lua\\nlocal root = WaitForPrimaryPart(character, 10)\\n\\nif root then\\n\\troot.CFrame = spawnCFrame\\nend\\n```","params":[{"name":"model","desc":"Model to wait on","lua_type":"Model"},{"name":"timeout","desc":"Seconds to wait before giving up (defaults to 5)","lua_type":"number?"}],"returns":[{"desc":"The primary part, or nil if the timeout elapsed","lua_type":"BasePart?"}],"function_type":"static","source":{"line":39,"path":"src/Shared/Modules/WaitForPrimaryPart.luau"}}],"properties":[],"types":[],"name":"WaitForPrimaryPart","desc":"Yields until a [Model] has a `PrimaryPart`, or until a timeout elapses.\\n\\nModels streamed in or replicated from the server can arrive before their\\n`PrimaryPart` is assigned; this polls on [RunService.Heartbeat] instead of\\nassuming the part is there.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":13,"path":"src/Shared/Modules/WaitForPrimaryPart.luau"}}')}}]);